//! Host setup and upstream-tool orchestration, using argument arrays without a shell.
//!
//! Downloads become visible only after SHA256 verification. GNU Radio receives
//! through a declarative GRC graph; its Python program is an ignored artifact
//! generated by the upstream compiler, not a maintained application script.

use std::fs::{self, File};
use std::io::{BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::thread;
use std::time::{Duration, Instant};

use anyhow::{Context, Result, bail, ensure};
use clap::Args;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use tempfile::NamedTempFile;

const PATCH: &str = "../../patches/gr-bladeRF-fedora.patch";
const GRAPH: &str = "tools/bladerf-lab/examples/gnuradio_rx.grc";
const GRAPH_BUILD: &str = "build/bladerf-lab/gnuradio-rx";

#[derive(Debug, Args)]
pub(crate) struct SetupArgs {
    /// Concurrent native build jobs (1..=128).
    #[arg(long, default_value_t = 4)]
    pub(crate) jobs: usize,
    /// Disable a DNF repository for this invocation; repeat for multiple repos.
    #[arg(long)]
    pub(crate) disable_repo: Vec<String>,
    /// Print the plan, including conditional actions, without changing the host.
    #[arg(long)]
    pub(crate) dry_run: bool,
}

#[derive(Debug, Args)]
pub(crate) struct GnuradioArgs {
    /// Number of complex samples, at most 10,000,000.
    #[arg(long, default_value_t = 200_000)]
    pub(crate) samples: usize,
    /// Requested RF center frequency in Hz.
    #[arg(long, default_value_t = 100e6)]
    pub(crate) frequency: f64,
    /// Requested complex samples per second.
    #[arg(long, default_value_t = 2e6)]
    pub(crate) sample_rate: f64,
    /// Requested manual RX gain in dB.
    #[arg(long, default_value_t = 20.0, allow_negative_numbers = true)]
    pub(crate) gain: f64,
    /// Device instance number or hexadecimal serial number.
    #[arg(long, default_value = "0")]
    pub(crate) device: String,
}

#[derive(Debug)]
struct CommandSpec {
    program: &'static str,
    args: Vec<String>,
    input: Option<&'static [u8]>,
    log: Option<&'static str>,
}

impl CommandSpec {
    fn new(program: &'static str, args: &[&str]) -> Self {
        Self {
            program,
            args: args.iter().map(|value| (*value).to_owned()).collect(),
            input: None,
            log: None,
        }
    }

    fn display(&self) {
        print!("{}", self.program);
        for arg in &self.args {
            print!(" {arg:?}");
        }
        if let Some(log) = self.log {
            print!(" [output: {log}]");
        }
        if let Some(input) = self.input {
            print!(" [stdin: {:?}]", String::from_utf8_lossy(input));
        }
        println!();
    }

    fn execute(&self) -> Result<()> {
        self.display();
        let mut command = Command::new(self.program);
        command.args(&self.args);
        if let Some(path) = self.log {
            let file = File::create(path).with_context(|| format!("create log {path}"))?;
            command.stdout(file.try_clone()?).stderr(file);
        }
        if let Some(input) = self.input {
            command.stdin(Stdio::piped()).stdout(Stdio::null());
            let mut child = command
                .spawn()
                .with_context(|| format!("start {}", self.program))?;
            let write_result = child
                .stdin
                .take()
                .context("child stdin was not available")?
                .write_all(input);
            if let Err(error) = write_result {
                let _ = child.kill();
                let _ = child.wait();
                return Err(error).context("write linker configuration to privileged tee");
            }
            ensure!(child.wait()?.success(), "{} failed", self.program);
        } else {
            let status = command
                .status()
                .with_context(|| format!("run {}", self.program))?;
            ensure!(status.success(), "{} exited with {status}", self.program);
        }
        Ok(())
    }
}

#[derive(Debug)]
enum SetupStep {
    Command(CommandSpec),
    Patch,
    Group,
    Directories,
    FetchImages,
}

fn native_build(source: &str, build: &str, extra: &[&str], jobs: usize) -> Vec<SetupStep> {
    let mut configure = CommandSpec::new(
        "cmake",
        &[
            "-S",
            source,
            "-B",
            build,
            "-G",
            "Ninja",
            "-DCMAKE_BUILD_TYPE=Release",
            "-DCMAKE_INSTALL_PREFIX=/usr/local",
        ],
    );
    configure
        .args
        .extend(extra.iter().map(|arg| (*arg).to_owned()));
    let mut compile = CommandSpec::new("cmake", &["--build", build, "--parallel"]);
    compile.args.push(jobs.to_string());
    let mut install = CommandSpec::new("sudo", &["cmake", "--install", build]);
    install.log = Some(match build {
        "build/bladeRF" => "artifacts/bladerf-install.log",
        "build/SoapyBladeRF" => "artifacts/soapy-install.log",
        _ => "artifacts/gr-bladerf-install.log",
    });
    vec![
        SetupStep::Command(configure),
        SetupStep::Command(compile),
        SetupStep::Command(install),
    ]
}

fn setup_steps(args: &SetupArgs) -> Result<Vec<SetupStep>> {
    ensure!(
        (1..=128).contains(&args.jobs),
        "jobs must be between 1 and 128"
    );
    ensure!(
        args.disable_repo
            .iter()
            .all(|repo| !repo.is_empty() && !repo.chars().any(char::is_control)),
        "repository names must be nonempty and contain no control characters"
    );
    let mut packages = CommandSpec::new("sudo", &["dnf"]);
    packages.args.extend(
        args.disable_repo
            .iter()
            .map(|repo| format!("--disable-repo={repo}")),
    );
    packages.args.extend(
        [
            "install",
            "-y",
            "git",
            "cmake",
            "ninja-build",
            "gcc",
            "gcc-c++",
            "pkgconf-pkg-config",
            "libusb1-devel",
            "libedit-devel",
            "ncurses-devel",
            "libcurl-devel",
            "SoapySDR-devel",
            "python3-devel",
            "python3-numpy",
            "gnuradio",
            "gnuradio-devel",
            "pybind11-devel",
            "python3-pybind11",
            "spdlog-devel",
            "fmt-devel",
            "gmp-devel",
            "boost-devel",
            "fontconfig-devel",
            "freetype-devel",
            "curl",
            "usbutils",
        ]
        .into_iter()
        .map(str::to_owned),
    );
    let mut steps = vec![
        SetupStep::Command(packages),
        SetupStep::Command(CommandSpec::new(
            "git",
            &["submodule", "update", "--init", "--recursive"],
        )),
        SetupStep::Patch,
        SetupStep::Group,
        SetupStep::Directories,
    ];
    steps.extend(native_build(
        "repos/bladeRF/host",
        "build/bladeRF",
        &["-DBLADERF_GROUP=plugdev", "-DINSTALL_UDEV_RULES=ON"],
        args.jobs,
    ));
    let mut linker = CommandSpec::new("sudo", &["tee", "/etc/ld.so.conf.d/bladerf-local.conf"]);
    linker.input = Some(b"/usr/local/lib\n/usr/local/lib64\n");
    steps.push(SetupStep::Command(linker));
    for arguments in [
        vec!["ldconfig"],
        vec!["udevadm", "control", "--reload-rules"],
        vec![
            "udevadm",
            "trigger",
            "--action=change",
            "--subsystem-match=usb",
            "--attr-match=idVendor=2cf0",
            "--attr-match=idProduct=5250",
        ],
        vec!["udevadm", "settle"],
    ] {
        steps.push(SetupStep::Command(CommandSpec::new("sudo", &arguments)));
    }
    steps.extend(native_build(
        "repos/SoapyBladeRF",
        "build/SoapyBladeRF",
        &[],
        args.jobs,
    ));
    steps.extend(native_build(
        "repos/gr-bladeRF",
        "build/gr-bladeRF",
        &[
            "-DCMAKE_INSTALL_LIBDIR=lib64",
            "-DPYTHON_EXECUTABLE=/usr/bin/python3",
            "-DENABLE_DOXYGEN=OFF",
        ],
        args.jobs,
    ));
    steps.push(SetupStep::Command(CommandSpec::new("sudo", &["ldconfig"])));
    steps.push(SetupStep::FetchImages);
    Ok(steps)
}

fn command_output(program: &str, args: &[&str]) -> Result<String> {
    let output = Command::new(program)
        .args(args)
        .output()
        .with_context(|| format!("run {program}"))?;
    ensure!(
        output.status.success(),
        "{program} failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    String::from_utf8(output.stdout).with_context(|| format!("{program} returned non-UTF8 text"))
}

fn apply_patch() -> Result<()> {
    let reverse = Command::new("git")
        .args([
            "-C",
            "repos/gr-bladeRF",
            "apply",
            "--reverse",
            "--check",
            PATCH,
        ])
        .output()
        .context("check existing GNU Radio compatibility patch")?;
    if reverse.status.success() {
        println!("gr-bladeRF compatibility patch is already applied.");
        return Ok(());
    }
    CommandSpec::new(
        "git",
        &["-C", "repos/gr-bladeRF", "apply", "--check", PATCH],
    )
    .execute()?;
    CommandSpec::new("git", &["-C", "repos/gr-bladeRF", "apply", PATCH]).execute()
}

fn ensure_group() -> Result<()> {
    let group = Command::new("getent")
        .args(["group", "plugdev"])
        .output()
        .context("inspect plugdev group")?;
    if !group.status.success() {
        ensure!(
            group.status.code() == Some(2),
            "getent failed while inspecting plugdev"
        );
        CommandSpec::new("sudo", &["groupadd", "--system", "plugdev"]).execute()?;
    }
    if !command_output("id", &["-nG"])?
        .split_whitespace()
        .any(|group| group == "plugdev")
    {
        let user = command_output("id", &["-un"])?;
        CommandSpec::new(
            "sudo",
            &["usermod", "--append", "--groups", "plugdev", user.trim()],
        )
        .execute()?;
        println!("Added your account to plugdev; log out and back in before accessing the radio.");
    }
    Ok(())
}

/// Rebuild the pinned native stack. Does not program the radio or enable TX.
pub(crate) fn setup_fedora(args: SetupArgs) -> Result<()> {
    let steps = setup_steps(&args)?;
    if args.dry_run {
        println!("Dry run: no package, filesystem, group, or hardware changes.");
    } else {
        let release = fs::read_to_string("/etc/os-release").context("read host distribution")?;
        ensure!(
            release
                .lines()
                .any(|line| line.trim() == "ID=fedora" || line.trim() == "ID=\"fedora\""),
            "setup targets Fedora; see docs/SETUP.md for other hosts"
        );
        ensure!(
            command_output("id", &["-u"])?.trim() != "0",
            "run as the regular user with sudo available"
        );
    }
    for step in steps {
        if args.dry_run {
            match step {
                SetupStep::Command(command) => command.display(),
                SetupStep::Patch => println!(
                    "Conditional: check reverse GNU Radio patch; if absent, git apply --check then git apply {PATCH} in repos/gr-bladeRF"
                ),
                SetupStep::Group => println!(
                    "Conditional: getent group plugdev; sudo groupadd --system plugdev if absent; id -nG; sudo usermod --append --groups plugdev CURRENT_USER if needed"
                ),
                SetupStep::Directories => {
                    println!("Create directories: artifacts, build, captures")
                }
                SetupStep::FetchImages => println!(
                    "Verify/download release images via fetch-images (SHA256 checked; no flashing)"
                ),
            }
            continue;
        }
        match step {
            SetupStep::Command(command) => command.execute()?,
            SetupStep::Patch => apply_patch()?,
            SetupStep::Group => ensure_group()?,
            SetupStep::Directories => {
                for directory in ["artifacts", "build", "captures"] {
                    fs::create_dir_all(directory).with_context(|| format!("create {directory}"))?;
                }
            }
            SetupStep::FetchImages => fetch_images()?,
        }
    }
    if !args.dry_run {
        println!("Host setup finished. Inspect the board with cargo run --locked -- doctor.");
    }
    Ok(())
}

fn compile_graph() -> Result<PathBuf> {
    fs::create_dir_all(GRAPH_BUILD).context("create generated GNU Radio program directory")?;
    CommandSpec::new("grcc", &["-o", GRAPH_BUILD, GRAPH]).execute()?;
    let path = Path::new(GRAPH_BUILD).join("gnuradio_rx.py");
    ensure!(path.is_file(), "grcc did not generate {}", path.display());
    Ok(path)
}

/// Inspect hardware and native tools without enabling a receive or transmit stream.
pub(crate) fn doctor() -> Result<()> {
    for command in [
        CommandSpec::new("lsusb", &["-d", "2cf0:5250"]),
        CommandSpec::new("bladeRF-cli", &["-p"]),
        CommandSpec::new("bladeRF-cli", &["-e", "info", "-e", "version"]),
        CommandSpec::new("SoapySDRUtil", &["--info"]),
        CommandSpec::new("SoapySDRUtil", &["--find=driver=bladerf"]),
        CommandSpec::new("gnuradio-config-info", &["--version"]),
    ] {
        command.execute()?;
    }
    compile_graph()?;
    println!("GNU Radio receive graph compiled. No stream was enabled.");
    Ok(())
}

#[derive(Debug)]
struct Image {
    url: &'static str,
    path: &'static str,
    sha256: &'static str,
}

const IMAGES: [Image; 2] = [
    Image {
        url: "https://www.nuand.com/fx3/bladeRF_fw_v2.6.0.img",
        path: "downloads/bladeRF_fw_v2.6.0.img",
        sha256: "a5f65bffd51107c09e36b45eda77593d900d975388bcfd83a9b6c3c45240b54a",
    },
    Image {
        url: "https://www.nuand.com/fpga/v0.16.0/hostedxA9.rbf",
        path: "downloads/hostedxA9-v0.16.0.rbf",
        sha256: "3004467110e2b2790c8f6128f998c2149905a88eed91a87f11af3db524d60c65",
    },
];

fn sha256(path: &Path) -> Result<String> {
    let mut reader =
        BufReader::new(File::open(path).with_context(|| format!("open {}", path.display()))?);
    let mut digest = Sha256::new();
    let mut buffer = [0_u8; 16_384];
    loop {
        let count = reader.read(&mut buffer)?;
        if count == 0 {
            break;
        }
        digest.update(&buffer[..count]);
    }
    Ok(format!("{:x}", digest.finalize()))
}

fn persist_verified(temporary: NamedTempFile, destination: &Path, expected: &str) -> Result<()> {
    ensure!(
        sha256(temporary.path())? == expected,
        "SHA256 mismatch; preserving {}",
        destination.display()
    );
    temporary
        .as_file()
        .sync_all()
        .context("sync verified image")?;
    temporary
        .persist(destination)
        .map_err(|error| error.error)
        .with_context(|| format!("install verified {}", destination.display()))?;
    Ok(())
}

/// Download official release images atomically after verification; never flash them.
pub(crate) fn fetch_images() -> Result<()> {
    fs::create_dir_all("downloads").context("create image directory")?;
    for image in IMAGES {
        let destination = Path::new(image.path);
        if destination.is_file() && sha256(destination)? == image.sha256 {
            println!("Verified {}", image.path);
            continue;
        }
        let temporary = tempfile::Builder::new()
            .prefix(".bladerf-image-")
            .tempfile_in("downloads")?;
        let status = Command::new("curl")
            .args([
                "--fail",
                "--location",
                "--retry",
                "3",
                "--connect-timeout",
                "20",
                "--max-time",
                "180",
                "--output",
            ])
            .arg(temporary.path())
            .args(["--url", image.url])
            .status()
            .context("download official image with curl")?;
        ensure!(
            status.success(),
            "download failed for {}; existing image preserved",
            image.url
        );
        persist_verified(temporary, destination, image.sha256)?;
        println!("Verified {}", image.path);
    }
    Ok(())
}

/// Guard a generated program so any error or timeout reaps its process.
struct ChildGuard(Child);

impl Drop for ChildGuard {
    fn drop(&mut self) {
        let _ = self.0.kill();
        let _ = self.0.wait();
    }
}

fn wait_bounded(child: &mut Child, timeout: Duration) -> Result<()> {
    let deadline = Instant::now() + timeout;
    loop {
        if let Some(status) = child.try_wait()? {
            ensure!(
                status.success(),
                "generated GNU Radio program exited with {status}"
            );
            return Ok(());
        }
        if Instant::now() >= deadline {
            child.kill().context("stop timed-out GNU Radio program")?;
            child.wait().context("reap timed-out GNU Radio program")?;
            bail!("GNU Radio capture timed out; no successful result recorded");
        }
        thread::sleep(Duration::from_millis(50));
    }
}

#[derive(Debug, Deserialize, Serialize)]
struct GnuradioResult {
    status: String,
    channel: String,
    complex_samples: usize,
    requested_frequency_hz: f64,
    requested_sample_rate_hz: f64,
    requested_gain_db: f64,
    bias_tee_enabled: bool,
    rms_dbfs: f64,
    continuity_note: String,
}

fn validate_gnuradio_args(args: &GnuradioArgs) -> Result<()> {
    ensure!(
        (1..=10_000_000).contains(&args.samples),
        "samples must be between 1 and 10,000,000"
    );
    ensure!(
        args.frequency.is_finite() && (70e6..=6e9).contains(&args.frequency),
        "frequency must be finite and in 70 MHz..=6 GHz"
    );
    ensure!(
        args.sample_rate.is_finite() && (520_834.0..=61.44e6).contains(&args.sample_rate),
        "sample rate must be finite and in 520834..=61440000 S/s"
    );
    ensure!(
        args.samples as f64 / args.sample_rate <= 60.0,
        "capture duration must be at most 60 seconds"
    );
    ensure!(
        args.gain.is_finite() && (-16.0..=60.0).contains(&args.gain),
        "gain must be finite and in -16..=60 dB"
    );
    ensure!(
        !args.device.is_empty()
            && args
                .device
                .chars()
                .all(|character| character.is_ascii_hexdigit()),
        "device must be an instance number or hexadecimal serial"
    );
    Ok(())
}

fn inspect_cf32(path: &Path, samples: usize) -> Result<f64> {
    ensure!(
        cfg!(target_endian = "little"),
        "the generated graph's native CF32 file requires the supported little-endian target"
    );
    let expected_bytes = u64::try_from(samples)?
        .checked_mul(8)
        .context("sample byte count overflow")?;
    ensure!(
        fs::metadata(path)?.len() == expected_bytes,
        "GNU Radio output length does not match {samples} complex samples"
    );
    let mut reader = BufReader::new(File::open(path)?);
    let mut pair = [0_u8; 8];
    let mut energy = 0.0_f64;
    for _ in 0..samples {
        reader.read_exact(&mut pair)?;
        let i = f32::from_le_bytes([pair[0], pair[1], pair[2], pair[3]]);
        let q = f32::from_le_bytes([pair[4], pair[5], pair[6], pair[7]]);
        ensure!(
            i.is_finite() && q.is_finite(),
            "GNU Radio output contains nonfinite IQ"
        );
        energy += f64::from(i).powi(2) + f64::from(q).powi(2);
    }
    ensure!(energy > 0.0, "GNU Radio output contains only zeros");
    Ok(10.0 * (energy / samples as f64).log10())
}

/// Run a finite RX1 graph and validate its generated CF32 output in Rust.
pub(crate) fn gnuradio_rx(args: GnuradioArgs) -> Result<()> {
    validate_gnuradio_args(&args)?;
    let program = compile_graph()?;
    fs::create_dir_all("artifacts")?;
    let output = tempfile::Builder::new()
        .prefix("gnuradio-rx-")
        .tempfile_in("artifacts")?;
    let mut child = ChildGuard(
        Command::new("python3")
            .arg(&program)
            .args([
                "--samples",
                &args.samples.to_string(),
                "--frequency",
                &args.frequency.to_string(),
                "--sample-rate",
                &args.sample_rate.to_string(),
                "--gain",
                &args.gain.to_string(),
                "--device",
                &args.device,
                "--output-path",
            ])
            .arg(output.path())
            .spawn()
            .context("start upstream-generated GNU Radio program")?,
    );
    wait_bounded(
        &mut child.0,
        Duration::from_secs_f64(args.samples as f64 / args.sample_rate + 15.0),
    )?;
    let rms_dbfs = inspect_cf32(output.path(), args.samples)?;
    let result = GnuradioResult {
        status: "PASS".to_owned(),
        channel: "RX1".to_owned(),
        complex_samples: args.samples,
        requested_frequency_hz: args.frequency,
        requested_sample_rate_hz: args.sample_rate,
        requested_gain_db: args.gain,
        bias_tee_enabled: false,
        rms_dbfs,
        continuity_note: "Untimestamped output does not certify absence of dropped samples"
            .to_owned(),
    };
    println!("{}", serde_json::to_string_pretty(&result)?);
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn corrupt_image_does_not_replace_existing_file() -> Result<()> {
        let directory = tempfile::tempdir()?;
        let destination = directory.path().join("image.rbf");
        fs::write(&destination, b"known good")?;
        let mut temporary = NamedTempFile::new_in(directory.path())?;
        temporary.write_all(b"corrupt download")?;
        assert!(persist_verified(temporary, &destination, "000000").is_err());
        assert_eq!(fs::read(&destination)?, b"known good");
        assert_eq!(fs::read_dir(directory.path())?.count(), 1);
        Ok(())
    }

    #[test]
    fn verified_image_replaces_destination() -> Result<()> {
        let directory = tempfile::tempdir()?;
        let destination = directory.path().join("image.rbf");
        fs::write(&destination, b"old")?;
        let mut temporary = NamedTempFile::new_in(directory.path())?;
        temporary.write_all(b"abc")?;
        persist_verified(
            temporary,
            &destination,
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
        )?;
        assert_eq!(fs::read(destination)?, b"abc");
        Ok(())
    }

    #[test]
    fn dnf_repository_input_is_one_argument() -> Result<()> {
        let args = SetupArgs {
            jobs: 4,
            disable_repo: vec!["repo;echo accidental".to_owned()],
            dry_run: true,
        };
        let steps = setup_steps(&args)?;
        let SetupStep::Command(packages) = &steps[0] else {
            panic!("package step expected")
        };
        assert!(
            packages
                .args
                .contains(&"--disable-repo=repo;echo accidental".to_owned())
        );
        assert!(!packages.args.contains(&"echo".to_owned()));
        Ok(())
    }

    #[test]
    fn invalid_build_and_capture_requests_fail_before_execution() {
        assert!(
            setup_steps(&SetupArgs {
                jobs: 0,
                disable_repo: Vec::new(),
                dry_run: true
            })
            .is_err()
        );
        let mut args = GnuradioArgs {
            samples: 100,
            frequency: f64::NAN,
            sample_rate: 2e6,
            gain: 20.0,
            device: "0".to_owned(),
        };
        assert!(validate_gnuradio_args(&args).is_err());
        args.frequency = 100e6;
        args.device = "0,trigger=True".to_owned();
        assert!(validate_gnuradio_args(&args).is_err());
    }

    #[test]
    fn cf32_output_rejects_incomplete_and_nonfinite_samples() -> Result<()> {
        let mut output = NamedTempFile::new()?;
        output.write_all(&f32::NAN.to_le_bytes())?;
        assert!(inspect_cf32(output.path(), 1).is_err());
        output.write_all(&0.0_f32.to_le_bytes())?;
        assert!(inspect_cf32(output.path(), 1).is_err());
        Ok(())
    }

    #[test]
    fn cf32_output_has_expected_complex_rms() -> Result<()> {
        let mut output = NamedTempFile::new()?;
        for value in [0.25_f32, 0.0, 0.0, 0.25] {
            output.write_all(&value.to_le_bytes())?;
        }
        assert!((inspect_cf32(output.path(), 2)? + 12.041_199_826_559_248).abs() < 1e-9);
        Ok(())
    }

    #[test]
    fn timeout_stops_and_reaps_generated_process() -> Result<()> {
        let mut child = Command::new("sleep").arg("5").spawn()?;
        assert!(wait_bounded(&mut child, Duration::from_millis(10)).is_err());
        assert!(child.try_wait()?.is_some());
        Ok(())
    }
}
